import React, { useEffect, useMemo, useState } from 'react';
import useAccountConfig from '../hooks/useAccountConfig';
import { HorarioAtencionData } from '../types';
import './PreferencesTab.css';

type DayKey = 'LUN' | 'MAR' | 'MIE' | 'JUE' | 'VIE' | 'SAB' | 'DOM';

interface TimeSlot {
  open: string; // "HH:MM"
  close: string; // "HH:MM"
}

interface PreferencesState {
  dashboardFotoUrl: string;
  envioDomicilio: boolean;
  colorBotones: string;
  colorFondo: string;
  display: {
    theme: 'light' | 'dark';
    language: 'es' | 'en';
    timezone: string;
  };
  schedule: Record<DayKey, TimeSlot[]>;
}

const DAYS: { key: DayKey; label: string }[] = [
  { key: 'LUN', label: 'Lunes' },
  { key: 'MAR', label: 'Martes' },
  { key: 'MIE', label: 'Miercoles' },
  { key: 'JUE', label: 'Jueves' },
  { key: 'VIE', label: 'Viernes' },
  { key: 'SAB', label: 'Sabado' },
  { key: 'DOM', label: 'Domingo' },
];

const emptyWeek = (): Record<DayKey, TimeSlot[]> => ({
  LUN: [],
  MAR: [],
  MIE: [],
  JUE: [],
  VIE: [],
  SAB: [],
  DOM: [],
});

const minutesToTime = (minutes: number): string => {
  const bounded = Math.max(0, Math.min(minutes, 24 * 60));
  const hours = Math.floor(bounded / 60);
  const mins = bounded % 60;
  return `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
};

const hydrateSchedule = (horarios?: HorarioAtencionData[] | null): Record<DayKey, TimeSlot[]> => {
  const schedule = emptyWeek();

  if (!horarios || horarios.length === 0) {
    return schedule;
  }

  horarios.forEach((item) => {
    const day = item.day as DayKey;
    if (!schedule[day]) {
      schedule[day] = [];
    }

    const slot: TimeSlot = {
      open: minutesToTime(item.abreMin),
      close: minutesToTime(item.cierraMin),
    };

    schedule[day][item.slotIndex] = slot;
  });

  (Object.keys(schedule) as DayKey[]).forEach((day) => {
    schedule[day] = schedule[day].filter(Boolean);
  });

  return schedule;
};

const PreferencesTab: React.FC = () => {
  const { empresaData, saving /*, updatePreferences*/ } = useAccountConfig();

  const initialPreferences = useMemo<PreferencesState>(() => {
    const prefs = empresaData?.preferenciasWeb;

    return {
      dashboardFotoUrl: prefs?.dashboardFoto ?? '',
      envioDomicilio: Boolean(prefs?.envioDomicilio),
      colorBotones: prefs?.colorBotones ?? '#0d6efd',
      colorFondo: prefs?.colorFondo ?? '#ffffff',
      display: {
        theme: prefs?.theme ?? 'light',
        language: prefs?.language ?? 'es',
        timezone: prefs?.timezone ?? 'America/Argentina/Buenos_Aires',
      },
      schedule: hydrateSchedule(prefs?.horarios),
    };
  }, [empresaData]);

  const [preferences, setPreferences] = useState<PreferencesState>(initialPreferences);
  const [dashboardFile, setDashboardFile] = useState<File | null>(null);

  useEffect(() => {
    setPreferences(initialPreferences);
  }, [initialPreferences]);

  const setField = <K extends keyof PreferencesState>(key: K, val: PreferencesState[K]) => {
    setPreferences((prev) => ({ ...prev, [key]: val }));
  };

  const setDisplayField = <K extends keyof PreferencesState['display']>(
    key: K,
    val: PreferencesState['display'][K],
  ) => {
    setPreferences((prev) => ({
      ...prev,
      display: { ...prev.display, [key]: val },
    }));
  };

  const addSlot = (day: DayKey) => {
    setPreferences((prev) => {
      const daySlots = prev.schedule[day] ?? [];
      const next: TimeSlot = { open: '09:00', close: '13:00' };

      return {
        ...prev,
        schedule: { ...prev.schedule, [day]: [...daySlots, next] },
      };
    });
  };

  const removeSlot = (day: DayKey, idx: number) => {
    setPreferences((prev) => {
      const daySlots = [...(prev.schedule[day] ?? [])];
      daySlots.splice(idx, 1);

      return {
        ...prev,
        schedule: { ...prev.schedule, [day]: daySlots },
      };
    });
  };

  const updateSlot = (day: DayKey, idx: number, field: keyof TimeSlot, value: string) => {
    setPreferences((prev) => {
      const daySlots = [...(prev.schedule[day] ?? [])];
      const slot = { ...daySlots[idx], [field]: value } as TimeSlot;
      daySlots[idx] = slot;

      return {
        ...prev,
        schedule: { ...prev.schedule, [day]: daySlots },
      };
    });
  };

  const isSlotValid = (slot: TimeSlot) => {
    const [oh, om] = slot.open.split(':').map(Number);
    const [ch, cm] = slot.close.split(':').map(Number);

    if ([oh, om, ch, cm].some((n) => Number.isNaN(n))) {
      return false;
    }

    const openMinutes = oh * 60 + om;
    const closeMinutes = ch * 60 + cm;

    return openMinutes >= 0 && closeMinutes <= 24 * 60 && openMinutes < closeMinutes;
  };

  const handleSavePreferences = async () => {
    const hasInvalid = Object.values(preferences.schedule).some((slots) =>
      slots.some((slot) => !isSlotValid(slot)),
    );

    if (hasInvalid) {
      alert(
        'Revisa los horarios: cada franja debe tener hora de apertura menor a la de cierre y formato HH:MM.',
      );
      return;
    }

    let dashboardFotoUrl = preferences.dashboardFotoUrl;

    if (dashboardFile) {
      // const uploadedUrl = await uploadToStorage(dashboardFile, `dashboards/${empresaData?.id}.jpg`);
      // dashboardFotoUrl = uploadedUrl;
    }

    const payload = {
      empresaId: empresaData?.id,
      colorBotones: preferences.colorBotones,
      colorFondo: preferences.colorFondo,
      envioDomicilio: preferences.envioDomicilio,
      dashboardFoto: dashboardFotoUrl || null,
      theme: preferences.display.theme,
      language: preferences.display.language,
      timezone: preferences.display.timezone,
      horarios: DAYS.flatMap(({ key }) =>
        (preferences.schedule[key] || []).map((slot, idx) => {
          const [oh, om] = slot.open.split(':').map(Number);
          const [ch, cm] = slot.close.split(':').map(Number);

          return {
            day: key,
            slotIndex: idx,
            abreMin: oh * 60 + om,
            cierraMin: ch * 60 + cm,
            cerrado: false,
          };
        }),
      ),
    };

    try {
      // await updatePreferences(payload);
      console.log('Payload a guardar:', payload);
      alert('Preferencias guardadas (demo). Integra la llamada a tu servicio.');
    } catch (error) {
      console.error(error);
      alert('No se pudieron guardar las preferencias.');
    }
  };

  return (
    <div className="preferences-tab">
      <div className="preferences-content">
        <div className="preferences-section">
          <h3>Preferencias Web</h3>

          <div className="preferences-grid">
            <div className="preference-item">
              <div className="preference-info">
                <h4>Foto Dashboard</h4>
                <p>Elige la imagen de fondo del dashboard</p>
                {preferences.dashboardFotoUrl && (
                  <div className="dashboard-preview">
                    <img
                      src={preferences.dashboardFotoUrl}
                      alt="Dashboard preview"
                    />
                  </div>
                )}
              </div>
              <div className="preference-control">
                <input
                  type="file"
                  accept="image/*"
                  onChange={(e) => {
                    const file = e.target.files?.[0] ?? null;
                    setDashboardFile(file);
                    if (file) {
                      const reader = new FileReader();
                      reader.onload = () => {
                        setField('dashboardFotoUrl', reader.result as string);
                      };
                      reader.readAsDataURL(file);
                    }
                  }}
                  title="Seleccionar imagen"
                />
              </div>
            </div>

            <div className="preference-item">
              <div className="preference-info">
                <h4>Envio a domicilio</h4>
                <p>Permite que los clientes pidan envio</p>
              </div>
              <label className="preference-control toggle-switch">
                <input
                  type="checkbox"
                  checked={preferences.envioDomicilio}
                  onChange={(e) => setField('envioDomicilio', e.target.checked)}
                />
                <span className="toggle-slider" />
              </label>
            </div>

            <div className="preference-item">
              <div className="preference-info">
                <h4>Color de botones</h4>
                <p>Selecciona el color de los botones en tu web</p>
              </div>
              <div className="preference-control">
                <input
                  type="color"
                  value={preferences.colorBotones}
                  onChange={(e) => setField('colorBotones', e.target.value)}
                  title="Color de botones"
                />
              </div>
            </div>

            <div className="preference-item">
              <div className="preference-info">
                <h4>Color de fondo</h4>
                <p>Selecciona el color de fondo de tu web</p>
              </div>
              <div className="preference-control">
                <input
                  type="color"
                  value={preferences.colorFondo}
                  onChange={(e) => setField('colorFondo', e.target.value)}
                  title="Color de fondo"
                />
              </div>
            </div>

            <div className="preference-item">
              <div className="preference-info">
                <h4>Tema</h4>
                <p>Claro u oscuro</p>
              </div>
              <select
                value={preferences.display.theme}
                onChange={(e) => setDisplayField('theme', e.target.value as 'light' | 'dark')}
              >
                <option value="light">Claro</option>
                <option value="dark">Oscuro</option>
              </select>
            </div>

            <div className="preference-item">
              <div className="preference-info">
                <h4>Idioma</h4>
                <p>Lenguaje por defecto</p>
              </div>
              <select
                value={preferences.display.language}
                onChange={(e) => setDisplayField('language', e.target.value as 'es' | 'en')}
              >
                <option value="es">Espanol</option>
                <option value="en">English</option>
              </select>
            </div>

            <div className="preference-item">
              <div className="preference-info">
                <h4>Zona horaria</h4>
                <p>Para evaluar estado abierto ahora</p>
              </div>
              <input
                type="text"
                value={preferences.display.timezone}
                onChange={(e) => setDisplayField('timezone', e.target.value)}
                placeholder="America/Argentina/Buenos_Aires"
              />
            </div>
          </div>
        </div>

        <div className="preferences-section schedule-section">
          <h3>Horarios de atencion</h3>
          <p className="muted">Agrega una o mas franjas por dia. Formato HH:MM.</p>

          <div className="schedule-grid">
            {DAYS.map(({ key, label }) => (
              <div key={key} className="schedule-day-card">
                <div className="schedule-day-header">
                  <h4>{label}</h4>
                  <button
                    type="button"
                    className="btn btn-sm"
                    onClick={() => addSlot(key)}
                  >
                    + Agregar franja
                  </button>
                </div>

                {(preferences.schedule[key] ?? []).length === 0 ? (
                  <div className="schedule-empty">Cerrado</div>
                ) : (
                  <div className="schedule-slots">
                    {preferences.schedule[key].map((slot, idx) => (
                      <div key={idx} className="slot-row">
                        <div className="slot-field">
                          <label>Abrir</label>
                          <input
                            type="time"
                            value={slot.open}
                            onChange={(e) => updateSlot(key, idx, 'open', e.target.value)}
                          />
                        </div>
                        <div className="slot-field">
                          <label>Cerrar</label>
                          <input
                            type="time"
                            value={slot.close}
                            onChange={(e) => updateSlot(key, idx, 'close', e.target.value)}
                          />
                        </div>
                        <button
                          type="button"
                          className="btn btn-danger btn-sm"
                          onClick={() => removeSlot(key, idx)}
                          title="Eliminar franja"
                        >
                          -
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="preferences-actions">
          <button
            className="btn btn-primary"
            onClick={handleSavePreferences}
            disabled={saving}
          >
            {saving ? 'Guardando...' : 'Guardar preferencias'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default PreferencesTab;
